import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  NavigationState,
  SceneRendererProps,
  TabBar,
  TabBarIndicator,
  TabView,
} from 'react-native-tab-view';
import {colorIndicator, IAuthenDocumentTab} from './helper';
import styles from './styles';
import DocumentListScreen from './tabScreens/document-authen-list';
import {View} from 'react-native';
import TextCM from '../../../components/Text';
import HeaderCM from '../../../components/Header/HeaderCM';

const renderTabBar = (
  props: SceneRendererProps & {
    navigationState: NavigationState<{
      key: string;
      title: string;
    }>;
  },
) => {
  const [activeTab, setActiveTab] = useState<IAuthenDocumentTab>(
    IAuthenDocumentTab.completed,
  );

  return (
    <TabBar
      {...props}
      indicatorStyle={[styles.indicatorStyle]}
      indicatorContainerStyle={styles.indicatorContainerStyle}
      style={styles.tabBarStyle}
      tabStyle={styles.tabStyle}
      inactiveColor="#667085"
      activeColor="red"
      contentContainerStyle={styles.contentContainerStyle}
      renderLabel={({route, focused, color}) => (
        <View style={styles.labelCtn}>
          <TextCM
            style={[
              styles.txtTabText,
              focused && {
                color: colorIndicator(route.key as IAuthenDocumentTab),
              },
            ]}>
            {route.title}
          </TextCM>
        </View>
      )}
      renderIndicator={({getTabWidth, position, navigationState}) => (
        <TabBarIndicator
          style={{
            backgroundColor: colorIndicator(
              navigationState.routes[navigationState.index]
                .key as IAuthenDocumentTab,
            ),
          }}
          layout={{
            width: getTabWidth(navigationState.index),
            height: 0,
          }}
          position={position}
          navigationState={navigationState}
          width={getTabWidth(navigationState.index)}
          getTabWidth={getTabWidth}
          jumpTo={() => {}}
          direction={'ltr'}
        />
      )}
    />
  );
};

const DocumentAuthenScreen = () => {
  const {t} = useTranslation();
  const [index, setIndex] = React.useState(0);

  const [routes] = React.useState([
    {key: IAuthenDocumentTab.completed, title: t('eContract.DC.DocumentAuthen.success')},
    {key: IAuthenDocumentTab.rejected, title: t('eContract.DC.DocumentAuthen.fail')},
    {key: IAuthenDocumentTab.processing, title: t('eContract.DC.DocumentAuthen.doing')},
  ]);

  const renderScene = ({route}: any) => {
    return <DocumentListScreen tab={route.key} />;
  };

  return (
    <View style={styles.ctnMain}>
      <HeaderCM
        title={t('eContract.DC.DocumentAuthen.label')}
        // isShowIconLeft={false}
        // containerStyle={styles.header}
      />
      <View style={{flex: 1}}>
        <TabView
          renderTabBar={renderTabBar}
          navigationState={{index, routes}}
          renderScene={renderScene}
          onIndexChange={setIndex}
        />
      </View>
    </View>
  );
};

export default DocumentAuthenScreen;
