
import {debounce, isEmpty} from 'lodash';
import {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {RefreshControl, ScrollView} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import styles from '../styles';
import InputSearch from '../image-signature/components/InputSearch';
import DigitalSignatureItem from './components/DigitalSignatureItem';
import {useNavigation} from '@react-navigation/native';
import { IImageDigitalSignature } from '../../../services/interface';
import { NavigationName } from '../../../constants';
import ButtonCM from '../../../components/Button';
import TextCM from '../../../components/Text';
import { View as ViewCM } from 'react-native';
import { useSettingStore } from '../../settings/store/settingStore';
import { useAccountServices } from '../../../hook/apiHook/useApi';

export type ModalAddType = 'ADD' | 'EDIT';

const DigitalSignature = () => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();

  const [listData, setListData] = useState<IImageDigitalSignature[]>([]);
  const [searchText, setSearchText] = useState('');
  const [debouncedSearchText, setDebouncedSearchText] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);

  const {isReloadingSign} = useSettingStore()

  const  accountServices = useAccountServices()

  const debouncedSearch = debounce((text: string) => {
    setDebouncedSearchText(text);
  }, 300);

  useEffect(() => {
    debouncedSearch(searchText);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchText]);

  useEffect(() => {
    getListData(debouncedSearchText);
  }, [debouncedSearchText.trim(), isReloadingSign]);

  const getListData = async (keyWord = '') => {
    try {
      const params = {
        name: keyWord,
      };
      const res = await accountServices.listImageDigitalSignature(params);
      const lsStar = res.filter(i => i.star);
      const lsUnStar = res.filter(i => !i.star);
      setListData([...lsStar, ...lsUnStar]);
    } catch (error) {
    } finally {
      setIsRefreshing(false);
    }
  };

  const renderItem = (item: IImageDigitalSignature) => {
    return (
      <DigitalSignatureItem key={item.id} data={item} onSuccess={onSuccess} />
    );
  };

  const onRefresh = () => {
    setIsRefreshing(true);
    getListData(debouncedSearchText);
  };

  const onSuccess = () => {
    getListData(debouncedSearchText);
  };

  const onPressAdd = () => {
    navigation.navigate(NavigationName.InfoDigitalSignature, {
      isNew: isEmpty(listData),
    });
  };

  return (
    <SafeAreaView style={styles.ctn} edges={['bottom']}>
      <InputSearch searchText={searchText} setSearchText={setSearchText} />
      <ScrollView
        style={styles.ctnView}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
        }>
        {isEmpty(listData) ? (
          <Nodata />
        ) : (
          <ViewCM>{listData.map(renderItem)}</ViewCM>
        )}
      </ScrollView>
      <ViewCM style={styles.btnAdd}>
        <ButtonCM label={t('eContract.AC.TxtAddDigitalSignature')} onPress={onPressAdd} />
      </ViewCM>
    </SafeAreaView>
  );
};

export default DigitalSignature;

const Nodata = () => {
  const {t} = useTranslation();
  return <TextCM style={styles.txtNoData}>{t('eContract.DC.TxtNoData')}</TextCM>;
};
