import {create} from 'zustand';
import {IConfigSecurityLogin} from '../../../services/interface';

interface genearalSettingFlowStore {
  currentEdit: IConfigSecurityLogin | null;
  currentHistory: IConfigSecurityLogin | null;
  listData: IConfigSecurityLogin[];
  setListData: (listData: IConfigSecurityLogin[]) => void;
  setCurrentEdit: (currentEdit: IConfigSecurityLogin | null) => void;
  setCurrentHistory: (currentHistory: IConfigSecurityLogin | null) => void;
}

const initialSettingState = {
  currentEdit: null,
  listData: [],
  currentHistory: null,
};

export const useGeneralSettingFlowStore = create<genearalSettingFlowStore>(
  (set, get) => ({
    ...initialSettingState,
    setListData: (listData: IConfigSecurityLogin[]) => {
      set({listData: listData});
    },
    setCurrentEdit: (currentEdit: IConfigSecurityLogin | null) => {
      set({currentEdit: currentEdit});
    },
    setCurrentHistory: (currentHistory: IConfigSecurityLogin | null) => {
      set({currentHistory: currentHistory});
    },
  }),
);
