import {useTranslation} from 'react-i18next';
import ChangeLanguage from './components/ChangeLanguage';
import TwoLayerAuthentication from './components/TwoLayerAuthentication';
import styles from './styles';
import {useFocusEffect, useNavigation} from '@react-navigation/native';
import {useAppDispatch, useAppSelector} from '../../hook/useRedux';
import React, {useState} from 'react';
import {ScrollView, TouchableOpacity} from 'react-native';
import {SizeDP} from '../../constants/Size';
import TextCM from '../../components/Text';
import SwitchCM from '../../components/Switch';
import {View as ViewCM} from 'react-native';
import {
  IconBlackClose,
  IconBlackRightArrow,
  IconBlueBell,
  IconBlueDocument,
  IconBlueFeedBack,
  IconBlueLanguage,
  IconBlueLock,
  IconBlueMessage,
  IconBlueQuestions,
  IconBlueTick,
  IconBlueUser,
  IconEngland,
  IconVietNam,
} from '../../assets/images';
import {NavigationName, String} from '../../constants';
import {isEmpty} from 'lodash';
import BottomSheetCM from '../../components/BottomSheet';
import HeaderCM from '../../components/Header/HeaderCM';
import ModalConfirm from '../../components/ModalConfirm';
import {commonActions} from '../../redux/slices';
import {useSettingStore} from './store/settingStore';
import {useAccountServices} from '../../hook/apiHook/useApi';
enum SettingsType {
  AccountInformation = 'AccountInformation',
  ChangePassword = 'ChangePassword',
  ConfigurationDigital = 'ConfigurationDigital',
  AuthAuthenticator = 'AuthAuthenticator',
  ReceiveNotification = 'ReceiveNotification',
  Language = 'Language',
  TermsOfUse = 'TermsOfUse',
  Feedback = 'Feedback',
  Questions = 'Questions',
  Logout = 'Logout',
  Biometrics = 'Biometrics',
}

type CategoryType = {
  label: string;
  icon: React.ReactNode;
  type: SettingsType;
  isIconRight?: boolean;
};

export enum Language {
  VietNam = 'vi',
  English = 'en',
}

const Settings = () => {
  const {t, i18n} = useTranslation();
  const navigation = useNavigation();
  const dispatch = useAppDispatch();

  const accountServices = useAccountServices();

  const {dataAccount} = useAppSelector(state => state.account);
  const common = useAppSelector(state => state.common);
  const language = useAppSelector(state => state.common.language);

  const {setTwoFactor, twoFactor} = useSettingStore();

  const activeTwoFactor = twoFactor.active;

  const [isVisibleChangeLanguage, setIsVisibleChangeLanguage] = useState(false);

  const [isVisibleAuthentication, setIsVisibleAuthentication] = useState(false);

  const [isVisibleLogout, setIsVisibleLogout] = useState(false);

  const [isShowConfirmOffTwoFactor, setIsShowConfirmOffTwoFactor] =
    useState(false);

  const LIST_CATEGORY: CategoryType[] = [
    {
      label: t('eContract.ST.TxtAccountInformation'),
      icon: <IconBlueUser width={SizeDP(16)} height={SizeDP(19)} />,
      type: SettingsType.AccountInformation,
    },
    {
      label: t('eContract.ST.TxtConfigurationDigital'),
      icon: <IconBlueMessage width={SizeDP(18)} height={SizeDP(14)} />,
      type: SettingsType.ConfigurationDigital,
    },
  ];

  const LIST_CATEGORY_SWITCH: CategoryType[] = [
    {
      label: t('eContract.ST.Txt2FAAuthenticator'),
      icon: <IconBlueTick width={SizeDP(18)} height={SizeDP(19)} />,
      type: SettingsType.AuthAuthenticator,
    },
  ];

  const LIST_CATEGORY_2: CategoryType[] = [
    {
      label: t('eContract.ST.TxtLanguage'),
      icon: <IconBlueLanguage width={SizeDP(20)} height={SizeDP(19)} />,
      type: SettingsType.Language,
      isIconRight: true,
    },
    {
      label: t('eContract.ST.TxtTermsOfUse'),
      icon: <IconBlueDocument width={SizeDP(14)} height={SizeDP(19)} />,
      type: SettingsType.TermsOfUse,
    },
    {
      label: t('eContract.ST.TxtFeedback'),
      icon: <IconBlueFeedBack width={SizeDP(23)} height={SizeDP(19)} />,
      type: SettingsType.Feedback,
    },
    {
      label: t('eContract.ST.TxtQuestions'),
      icon: <IconBlueQuestions width={SizeDP(18)} height={SizeDP(20)} />,
      type: SettingsType.Questions,
    },
    // {
    //   label: t('eContract.ST.TxtLogout'),
    //   icon: <IconBlueLogout width={SizeDP(19)} height={SizeDP(17)} />,
    //   type: SettingsType.Logout,
    // },
  ];

  const getIconLanguage = () => {
    const lang = language ?? i18n.language;
    if (lang === Language.VietNam) {
      return <IconVietNam width={SizeDP(28)} height={SizeDP(18)} />;
    }
    return <IconEngland width={SizeDP(28)} height={SizeDP(18)} />;
  };

  const getIconRightItem = (type: SettingsType) => {
    if (type === SettingsType.Language) {
      return getIconLanguage();
    }
    return null;
  };

  const renderItem = (item: CategoryType) => {
    const onPressItem = () => {
      switch (item.type) {
        case SettingsType.AccountInformation:
          navigation.navigate(NavigationName.AccountInfo as never);
          break;
        case SettingsType.AuthAuthenticator:
          toggleModalAuthentication();
          break;
        case SettingsType.Feedback:
          navigation.navigate(NavigationName.FeedbackScreen as never);
          break;
        case SettingsType.TermsOfUse:
          navigation.navigate(NavigationName.TermUseScreen as never);
          break;
        case SettingsType.Language:
          toggleModalChangeLanguage();
          break;
        case SettingsType.ConfigurationDigital:
          navigation.navigate(NavigationName.DigitalCertificate as never);
          break;
        case SettingsType.ChangePassword:
          navigation.navigate(NavigationName.ChangePassword as never);
          break;
        case SettingsType.Logout:
          onPressLogout();
          break;
        default:
          break;
      }
    };

    return (
      <TouchableOpacity
        key={item.type}
        style={styles.viewItem}
        onPress={onPressItem}>
        <ViewCM style={styles.viewIcon}>{item.icon}</ViewCM>
        <TextCM style={styles.txtItem}>{item.label}</TextCM>
        {item.isIconRight && getIconRightItem(item.type)}
        {item.type !== SettingsType.Logout && (
          <IconBlackRightArrow width={SizeDP(12)} height={SizeDP(18)} />
        )}
      </TouchableOpacity>
    );
  };

  const renderItemToggle = (item: CategoryType) => {
    const onPress = () => {
      onToggleItem(item.type);
    };

    return (
      <ViewCM key={item.type} style={styles.viewItem}>
        <ViewCM style={styles.viewIcon}>{item.icon}</ViewCM>
        <TextCM style={styles.txtItem}>{item.label}</TextCM>
        <SwitchCM
          disable={
            item.type === SettingsType.AuthAuthenticator &&
            twoFactor.active &&
            isEmpty(twoFactor?.orgIn)
          }
          isEnabled={getEnabledToggle(item.type)}
          onPress={onPress}
        />
      </ViewCM>
    );
  };

  const onToggleItem = (type: SettingsType) => {
    switch (type) {
      case SettingsType.AuthAuthenticator:
        handleAuthenticator();
        break;
      default:
        break;
    }
  };

  const getEnabledToggle = (type: SettingsType) => {
    switch (type) {
      case SettingsType.AuthAuthenticator:
        if (twoFactor.active) return true;
        return activeTwoFactor;
      default:
        return false;
    }
  };

  useFocusEffect(
    React.useCallback(() => {
      const email = dataAccount.email;
      accountServices.fetchTwoFactorState(email).then(res => {
        setTwoFactor(res.data);
      });
    }, []),
  );

  const handleAuthenticator = () => {
    if (activeTwoFactor) {
      setIsShowConfirmOffTwoFactor(true);
    } else {
      setIsVisibleAuthentication(true);
    }
  };

  const onTurmOffTwoFactor = () => {
    const email = dataAccount.email;
    const contactTrace = common.devicesInfo;
    const type = twoFactor.type;
    accountServices
      .turnOffTwoFactor({email, contactTrace, type, status: false})
      .then(res => {
        setTwoFactor(res.data);
      });
    toggleConfirmOffTwoFactor();
  };

  const onPressLogout = () => {
    toggleModalLogout();
  };

  const toggleModalChangeLanguage = () => {
    setIsVisibleChangeLanguage(!isVisibleChangeLanguage);
  };

  const toggleModalAuthentication = () => {
    setIsVisibleAuthentication(!isVisibleAuthentication);
  };

  const toggleModalLogout = () => {
    setIsVisibleLogout(!isVisibleLogout);
  };

  const toggleConfirmOffTwoFactor = () => {
    setIsShowConfirmOffTwoFactor(!isShowConfirmOffTwoFactor);
  };

  const onChangeLanguage = (type: string) => {
    dispatch(commonActions.updateLanguage(type));
    updateLanguageAccount(type);
    toggleModalChangeLanguage();
  };

  const updateLanguageAccount = async (language: string) => {
    const body = {
      activated: dataAccount.activated,
      address: dataAccount.address,
      authorities: dataAccount.authorities,
      dob: dataAccount.dob,
      firstName: dataAccount.firstName,
      gender: dataAccount.gender,
      imageUrl: dataAccount.imageUrl,
      langKey: language ?? i18n.language,
      lastName: dataAccount.lastName,
      login: dataAccount.login,
      phone: dataAccount.phone,
    };
    accountServices.postUpdateInfo(body);
  };

  return (
    <ViewCM style={styles.ctnMain}>
      <HeaderCM title={t('eContract.ST.TxtSettingAccount')} />
      <ScrollView
        style={styles.mainContainer}
        showsVerticalScrollIndicator={false}>
        <ViewCM style={styles.body}>
          {LIST_CATEGORY.map(renderItem)}
          {LIST_CATEGORY_SWITCH.map(renderItemToggle)}
          {LIST_CATEGORY_2.map(renderItem)}
        </ViewCM>
      </ScrollView>
      <BottomSheetCM
        isVisible={isVisibleChangeLanguage}
        title={t('eContract.ST.TxtChangeLanguage')}
        onClose={toggleModalChangeLanguage}
        iconClose={<IconBlackClose width={SizeDP(12)} height={SizeDP(12)} />}
        renderContent={
          <ChangeLanguage
            onCancel={toggleModalChangeLanguage}
            onConfirm={onChangeLanguage}
            currentLanguage={language ?? i18n.language}
          />
        }
      />
      <BottomSheetCM
        isVisible={isVisibleAuthentication}
        title={t('eContract.ST.Txt2FAAuthenticator')}
        onClose={toggleModalAuthentication}
        iconClose={<IconBlackClose width={SizeDP(12)} height={SizeDP(12)} />}
        renderContent={
          <TwoLayerAuthentication
            onCancel={toggleModalAuthentication}
            onConfirm={toggleModalAuthentication}
          />
        }
      />

      <ModalConfirm
        type="delete"
        onConfirm={onTurmOffTwoFactor}
        onClose={toggleConfirmOffTwoFactor}
        isVisible={isShowConfirmOffTwoFactor}
        title={t('eContract.ST.TwoFactor.twoFactorAuthen')}
        content={t('eContract.ST.TwoFactor.confirmTurnOffTwoAuthen')}
        labelConfirm={t('eContract.CM.Agree')}
      />
    </ViewCM>
  );
};

export default Settings;
