import {useNavigation} from '@react-navigation/native';
import {isEmpty} from 'lodash';
import React from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity, View} from 'react-native';
import {IRelatedDocument} from '../../helper';
import styles from './styles';
import {IDocument} from '../../../../../model/interface/envelope.interface';
import Toast from 'react-native-toast-message';
import {DateUtils} from '../../../../../utils';
import TextCM from '../../../../../components/Text';
import {IconBlueCheck} from '../../../../../assets/images';

type Props = {
  data: IDocument;
  tabKey: IRelatedDocument;
  isSelected?: boolean;
  onPressItem?: (IDocument: IDocument) => void;
};
const RelateDocumentItem = ({
  data,
  tabKey,
  isSelected = false,
  onPressItem,
}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();

  const showError = () => {
    Toast.show({
      type: 'error',
      text1: t('eContract.CM.TxtSystemError'),
    });
  };

  const getDataDateDone = () => {
    return DateUtils.convertDateToDDMMYYYY(data.flowFinishDate);
  };

  const getNameUserCreate = () => {
    if (tabKey === IRelatedDocument.myDocument) return '';
    return data.owner;
  };
  const onPressDocument = () => {
    if (onPressItem) {
      onPressItem(data);
    }
  };

  return (
    <TouchableOpacity
      style={[styles.container, isSelected && {backgroundColor: '#E6F2FB'}]}
      onPress={onPressDocument}>
      <View style={styles.header}>
        <View style={styles.viewTitle}>
          <TextCM style={[styles.txtTitle]}>{data.name.trim()}</TextCM>
          {isSelected && <IconBlueCheck width={16} height={16} />}
        </View>
      </View>
      <View style={styles.viewCode}>
        <TextCM style={styles.txtCode}>{data.envNo || '---'}</TextCM>
      </View>
      <View style={styles.viewList}>
        {getNameUserCreate() && (
          <View style={styles.viewItem}>
            <TextCM style={styles.txtName}>{t('eContract.DC.TxtUserCreate')}</TextCM>
            <TextCM style={styles.txtValue}>{getNameUserCreate()}</TextCM>
          </View>
        )}
        <View style={styles.viewItem}>
          <TextCM style={styles.txtName}>{t('eContract.DC.TxtDoneDate')}</TextCM>
          <TextCM style={styles.txtValue}>{getDataDateDone()}</TextCM>
        </View>
        <View style={styles.viewItem}>
          <TextCM style={styles.txtName}>{t('eContract.DC.TxtParties')}</TextCM>
          <View style={styles.viewValueParties}>
            {!isEmpty(data?.parties) ? (
              data?.parties?.map((item: any, index: number) => {
                return (
                  <TextCM style={styles.txtValue} key={item.id}>
                    {item.type !== 'individual'
                      ? item.name || '---'
                      : item.recipients?.[0]?.contact?.name}
                  </TextCM>
                );
              })
            ) : (
              <TextCM style={styles.txtValue}>---</TextCM>
            )}
          </View>
        </View>
      </View>
    </TouchableOpacity>
  );
};

export default RelateDocumentItem;
