import {isEmpty} from 'lodash';
import {FC, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {useAppSelector} from '../../../../../hook/useRedux';
import {ICreateTemplateMessage} from '../../../../../model/interface/notification.interface';
import Toast from 'react-native-toast-message';
import ButtonCM from '../../../../../components/Button';
import React from 'react';
import {useCreateNotiServices} from '../../../../../hook/apiHook/useApi';
import TextFieldCM from '../../../../../components/TextField';

type Props = {
  onClose: () => void;
};

const RenderCreateTemplate: FC<Props> = ({onClose}) => {
  const [valueTemplateMessage, setValueTemplateMessage] = useState<string>('');
  const account = useAppSelector(state => state.account.dataAccount);
  const {t} = useTranslation();

  const NotificationServices = useCreateNotiServices();

  const handleSubmitCreateTemplateMessage = async () => {
    try {
      const body: ICreateTemplateMessage = {
        aliasName: null,
        content: valueTemplateMessage.trim(),
        createdBy: null,
        createdDate: null,
        custId: account.custId,
        format: 'text',
        id: null,
        lastModifiedBy: null,
        lastModifiedDate: null,
        orgIn: account.orgIn,
        owner: account.email?.toLowerCase(),
        priority: 0,
      };
      await NotificationServices.createTemplateMessage(body);
      Toast.show({
        type: 'success',
        text1: t('eContract.NT.message.successCreateTemplateMessage'),
      });
    } catch (error) {
    } finally {
      onClose();
    }
  };

  return (
    <>
      <TextFieldCM
        label={t('eContract.NT.content')}
        isRequired
        value={valueTemplateMessage}
        multiline
        maxLength={100}
        onChangeText={setValueTemplateMessage}
      />
      <ButtonCM
        disabled={isEmpty(valueTemplateMessage.trim())}
        style={{marginTop: 10}}
        label={t('eContract.CM.TxtSave')}
        onPress={handleSubmitCreateTemplateMessage}
      />
    </>
  );
};

export default RenderCreateTemplate;
