import {isEmpty} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  Dimensions,
  Modal,
  ScrollView,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {
  IExtendedRelateDocument,
  convertToHierarchy,
  handleContextPath,
  toggleNode,
} from './helper';
import styles from './styles';
import TextCM from '../../../../../components/Text';
import {
  IcBlackLeftArrow,
  IconBlackDownArrow,
  IconBlackRightArrow,
  IconRedFillTrash,
} from '../../../../../assets/images';
import ModalConfirm from '../../../../../components/ModalConfirm';
import {Font} from '../../../../../constants';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type ModalRelateDocumentProp = {
  onClose: () => void;
  isVisible: boolean;
  envelopeId: string;
};

const ModalRelateDocument = ({
  onClose,
  isVisible,
  envelopeId,
}: ModalRelateDocumentProp) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const [data, setData] = useState<IExtendedRelateDocument[]>([]);
  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const [selectedContext, setSelectedContext] = useState('');

  const DocumentServices = useDocumentServices();

  const toggleShowChildren = (id: string) => {
    setData(toggleNode(data, id));
  };

  const toggleModalConfirm = () => {
    setShowModalConfirm(!showModalConfirm);
  };

  const onPressDeleteItem = (contextPath: string) => {
    setSelectedContext(contextPath);
    toggleModalConfirm();
  };

  const onPressConfirmDelete = async () => {
    try {
      const res = await DocumentServices.deleteRelatedDocument(selectedContext);
    } catch (error) {
    } finally {
      getData(true);
      toggleModalConfirm();
    }
  };

  useEffect(() => {
    getData(false);
  }, []);

  const getData = async (showChildren: boolean) => {
    try {
      const res = await DocumentServices.getRelateDocument(envelopeId);
      setData(convertToHierarchy(res, showChildren));
    } catch (error) {}
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View
          style={[
            styles.ctnContent,
            {
              paddingBottom: insets.bottom,
              height: (Dimensions.get('window').height / 4) * 3,
            },
          ]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('eContract.DC.TxtSuggestionDocument')}
            </TextCM>
            <View />
          </View>
          <ScrollView style={styles.viewBody}>
            <View style={styles.ctnHierachyView}>
              {renderHierachyView(data, toggleShowChildren, onPressDeleteItem)}
            </View>
          </ScrollView>
        </View>
      </View>
      <ModalConfirm
        onConfirm={onPressConfirmDelete}
        onClose={toggleModalConfirm}
        isVisible={showModalConfirm}
        title={t('eContract.DC.confirmDeleteRelatedDocument')}
      />
    </Modal>
  );
};

export default ModalRelateDocument;

const renderHierachyView = (
  data: IExtendedRelateDocument[],
  onPress: (id: string) => void,
  onPressDelete: (contextPath: string) => void,
) => {
  const handleOnPress = (id: string) => {
    onPress(id);
  };
  return (
    <View style={styles.ctnGap}>
      {data.map(item => {
        const isShowChildItem = item.showChildren && item.children.length !== 0;
        return (
          <View style={styles.ctnGap} key={item.contextPath}>
            <DocumentItem
              onPress={handleOnPress}
              data={item}
              onPressDelete={onPressDelete}
            />
            {isShowChildItem && (
              <View style={{marginLeft: 10}}>
                {renderHierachyView(item.children, onPress, onPressDelete)}
              </View>
            )}
          </View>
        );
      })}
    </View>
  );
};

const DocumentItem = ({
  data,
  onPress,
  onPressDelete,
}: {
  data: IExtendedRelateDocument;
  onPress: (id: string) => void;
  onPressDelete: (id: string) => void;
}) => {
  const handleOnpress = () => {
    if (onPress) {
      onPress(data.id);
    }
  };

  const handleOnDelete = () => {
    const id = handleContextPath(data.contextPath);
    onPressDelete(id);
  };

  const customStyle =
    data.level > 0
      ? {fontFamily: Font.InterRegular400}
      : data.level < 0
      ? {fontFamily: Font.InterSemiBold600}
      : {};

  return (
    <View style={styles.itemCtn}>
      <TouchableOpacity
        disabled={isEmpty(data.children)}
        onPress={handleOnpress}
        style={[
          styles.rowDocument,
          {
            flex: 1,
          },
        ]}>
        {data.level > 0 ? (
          <TextCM style={[styles.txtItem]}>•</TextCM>
        ) : data.showChildren ? (
          <IconBlackDownArrow width={12} height={12} />
        ) : (
          <IconBlackRightArrow width={12} height={12} />
        )}
        <View style={styles.underLine}>
          <TextCM
            style={[
              styles.txtItem,
              customStyle,
              {
                flex: 1,
                marginRight: 4,
              },
            ]}>
            {data.name}
          </TextCM>
        </View>
      </TouchableOpacity>
      {data.level > 0 && (
        <TouchableOpacity onPress={handleOnDelete}>
          <IconRedFillTrash width={14} height={14} />
        </TouchableOpacity>
      )}
    </View>
  );
};
