import {useRoute} from '@react-navigation/native';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, TouchableOpacity, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';

import styles from './styles';
import {isEmpty} from 'lodash';
import ModalListDocumentError from './ModalCreateBatchesDocument';
import {
  IBatches,
  IDocument,
  IDocumentError,
} from '../../../model/interface/envelope.interface';
import TextCM from '../../../components/Text';
import {DateUtils} from '../../../utils';
import HeaderCM from '../../../components/Header/HeaderCM';
import {useDocumentServices} from '../../../hook/apiHook/useApi';

const DocumentTemplateHistory = () => {
  const route = useRoute<any>();
  const {id}: IDocument = route.params.data;
  const {t} = useTranslation();

  const [data, setData] = useState<IBatches[]>([]);
  const [showModal, setShowModal] = useState<boolean>(false);
  const [dataListDocumentError, setListDocumentError] = useState<
    IDocumentError[]
  >([]);

  const DocumentServices = useDocumentServices();

  const getListBatches = () => {
    DocumentServices.getListBatches(id).then(data => {
      if (!isEmpty(data)) {
        const sortedData = data
          .sort(
            (a: IBatches, b: IBatches) =>
              (b.errCount > 0 ? 1 : 0) - (a.errCount > 0 ? 1 : 0),
          )
          .sort(
            (a: IBatches, b: IBatches) =>
              new Date(b.createdDate).getTime() -
              new Date(a.createdDate).getTime(),
          );
        setData(sortedData);
      }
    });
  };

  useEffect(() => {
    getListBatches();
  }, []);

  const onCloseModal = () => {
    setShowModal(false);
  };

  const onPressItem = (item: IBatches) => {
    DocumentServices.getListDocumentError(item.id).then(data => {
      if (!isEmpty(data)) {
        setListDocumentError(data);
        setShowModal(true);
      }
    });
  };

  const renderItem = ({item, index}: {item: IBatches; index: number}) => {
    return (
      <TouchableOpacity
        disabled={item.errCount > 0 ? false : true}
        onPress={() => onPressItem(item)}
        style={styles.ctnMainItem}
        key={index}>
        <TextCM
          style={[
            styles.txtTitle,
            {color: item.errCount > 0 ? '#0673C6' : '#262D34'},
          ]}>
          {item.id}
        </TextCM>
        <View style={styles.ctnViewItem}>
          <TextCM style={styles.txtTitleItem}>{t('eContract.DC.TxtCreateDate')}</TextCM>
          <TextCM style={styles.txtValueItem}>
            {DateUtils.convertDateToDDMMYYYY(item.createdDate)}
          </TextCM>
        </View>
        <View style={styles.ctnViewItem}>
          <TextCM style={styles.txtTitleItem}>
            {t('eContract.DC.TxtTotalNumberOfDocuments')}
          </TextCM>
          <TextCM style={[styles.txtValueItem, styles.txtTotleDocument]}>
            {item.total}
          </TextCM>
        </View>
        <View style={styles.ctnViewItem}>
          <TextCM style={styles.txtTitleItem}>
            {t('eContract.DC.TxtTotalNumberOfDocumentsError')}
          </TextCM>
          <TextCM style={[styles.txtValueItem, styles.txtTotleDocumentError]}>
            {item.errCount}
          </TextCM>
        </View>
      </TouchableOpacity>
    );
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <HeaderCM title={t('eContract.DC.TxtListBatches')} />
      <FlatList
        keyExtractor={item => item.id.toString()}
        data={data}
        renderItem={renderItem}
        ListEmptyComponent={<Nodata />}
      />
      <ModalListDocumentError
        isVisible={showModal}
        onClose={onCloseModal}
        data={dataListDocumentError}
        handleCallBack={getListBatches}
      />
    </SafeAreaView>
  );
};

const Nodata = () => {
  const {t} = useTranslation();
  return <TextCM style={styles.txtNoData}>{t('eContract.DC.TxtNoData')}</TextCM>;
};

export default DocumentTemplateHistory;
