import {create} from 'zustand';
import {INotification} from '../../../model/interface/notification.interface';

interface NotificationState {
  reLoadDataNotification: boolean;
  listNotifications: INotification[];
  currentSignDozens: INotification[];
  imageSignature: string;
  setReloadDataNotification: (value: boolean) => void;
  setListNotifications: (value: INotification[]) => void;
  setCurrentSignDozens: (value: INotification[]) => void;
  setImageSignature: (value: string) => void;
  toggleItemSignDozen: (value: INotification) => void;
}

const initialNotificationState: NotificationState = {
  reLoadDataNotification: false,
  listNotifications: [],
  currentSignDozens: [],
  imageSignature: '',
  setReloadDataNotification: () => {},
  setListNotifications: () => {},
  setCurrentSignDozens: () => {},
  setImageSignature: () => {},
  toggleItemSignDozen: () => {},
};

const useStoreNoti = create<NotificationState>(set => ({
  ...initialNotificationState,
  setReloadDataNotification: value =>
    set(state => ({...state, reLoadDataNotification: value})),
  setListNotifications: value =>
    set(state => ({...state, listNotifications: value})),
  setCurrentSignDozens: value =>
    set(state => ({...state, currentSignDozens: value})),
  setImageSignature: value => set(state => ({...state, imageSignature: value})),
  toggleItemSignDozen: value =>
    set(state => {
      const index = state.currentSignDozens.findIndex(
        item => item.id === value.id,
      );
      const newCurrentSignDozens = [...state.currentSignDozens];
      if (index === -1) {
        newCurrentSignDozens.push(value);
      } else {
        newCurrentSignDozens.splice(index, 1);
      }
      return {...state, currentSignDozens: newCurrentSignDozens};
    }),
}));

export default useStoreNoti;
