export const ALL_PERMISSION = [
  {id: 'v_d', label: 'eContract.DC.ShareDocument.permVD'},
  {id: 'v', label: 'eContract.DC.ShareDocument.permV'},
];

export const TYPE_OF_SHARE = [
  {id: 'email', label: 'eContract.DC.ShareDocument.shareByEmail'},
];

export const LIST_PERMISSION = [{id: 'v_d', label: 'eContract.DC.ShareDocument.permVD'}];

export const getPermissionLabelById = (id: string) => {
  const permission = ALL_PERMISSION.find(permission => permission.id === id);
  return permission ? permission.label : 'Label not found';
};
