import { IconBlueDelete, IconBlueFile, IconBlueFullfillPen } from "../../../assets/images";
import { SizeDP } from "../../../constants/Size";

export enum IAutoConfigAction {
  /** Xem lịch sử*/
  watchHisory = 'watchHisory',
  /** Xóa cấu hình */
  deleteConfig = 'deleteConfig',
  /** Sửa cấu hình*/
  editConfig = 'editConfig',
}

export enum IAutoConfigSignType {
  /** Ký ảnh*/
  'Sign-Image' = 'Sign-Image',
  /** Text*/
  'text_control' = 'text_control',
  /** sign_fca.passcode */
  'sign_fca.passcode' = 'sign_fca.passcode',
}

export const mappingSignType = (key: string) => {
  switch (key) {
    case IAutoConfigSignType['Sign-Image']:
      return 'eContract.GS.autoConfig.txtSignImage';
    case IAutoConfigSignType['text_control']:
      return 'eContract.GS.autoConfig.txtSignText';
    case IAutoConfigSignType['sign_fca.passcode']:
      return 'eContract.GS.autoConfig.txtFcaPasscode';
    default:
      return 'eContract.GS.autoConfig.txtFcaPasscode';
  }
};

export const getListActions = () => {
  return [
    {
      name: 'eContract.GS.autoConfig.watchHistory',
      icon: <IconBlueFile width={SizeDP(14)} height={SizeDP(18)} />,
      type: IAutoConfigAction.watchHisory,
    },
    {
      name: 'eContract.GS.autoConfig.deleteConfig',
      icon: <IconBlueDelete width={SizeDP(16)} height={SizeDP(18)} />,
      type: IAutoConfigAction.deleteConfig,
    },
    {
      name: 'eContract.GS.autoConfig.editConfig',
      icon: <IconBlueFullfillPen width={SizeDP(18)} height={SizeDP(18)} />,
      type: IAutoConfigAction.editConfig,
    },
  ];
};
