import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  ActivityIndicator,
  Modal,
  ScrollView,
  TouchableOpacity,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import styles from './styles';
import ModalDetailHistoyPassword from '../ModalDetailHistoyPassword';
import { mappingMethod } from './helper';
import { IHistoryPassword } from '../../../../../services/interface';
import { useGeneralSettingServices } from '../../../../../hook/apiHook/useApi';
import TextCM from '../../../../../components/Text';
import { View as ViewCM } from 'react-native';
import { DateUtils } from '../../../../../utils';
import { IcBlackLeftArrow } from '../../../../../assets/images';
import { SizeDP } from '../../../../../constants/Size';
import ButtonCM from '../../../../../components/Button';

type ModalHistoryPasswordProp = {
  onClose: () => void;
  isVisible: boolean;
  id: number;
};

const ModalHistoryPassword = ({
  onClose,
  isVisible,
  id,
}: ModalHistoryPasswordProp) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const [history, setHistory] = useState<IHistoryPassword[]>([]);
  const generalSettingServices = useGeneralSettingServices()

  const [showModalDetail, setShowModalDetail] = useState(false);

  const [currentShow, setCurrentShow] = useState(0);

  const [loading, setLoading] = useState(false);

  const toggleModalDetail = () => {
    setShowModalDetail(!showModalDetail);
  };

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    try {
      setLoading(true);
      const res = await generalSettingServices.getHistoryPassword(id);
      setHistory(res.reverse());
    } catch (error) {
    } finally {
      setLoading(false);
    }
  };

  const renderHistory = () => {
    return (
      <ScrollView style={{flex: 1}} showsVerticalScrollIndicator={false}>
        <ViewCM>
          <TextCM style={styles.txtLabel}>{t('eContract.DC.infoHistory')}</TextCM>
        </ViewCM>
        <ViewCM style={styles.groupItem}>
          {history.map((item: IHistoryPassword, index: number) => {
            const methodMapping = mappingMethod(item.method);
            const onPress = () => {
              toggleModalDetail();
              setCurrentShow(item.id);
            };
            return (
              <ViewCM key={index.toString()}>
                <TouchableOpacity onPress={onPress} style={styles.item}>
                  <ViewCM style={styles.rowInfo}>
                    <TextCM style={styles.txtItemTitle}>
                      {item?.createdBy}
                    </TextCM>
                  </ViewCM>
                  <ViewCM style={styles.rowInfo}>
                    <TextCM style={styles.txt400small}>
                      {t('eContract.GS.history.operate')}
                    </TextCM>
                    <TextCM
                      style={[
                        styles.txt500small,
                        {color: methodMapping.color},
                      ]}>
                      {t(methodMapping.label)}
                    </TextCM>
                  </ViewCM>
                  <ViewCM style={styles.rowInfo}>
                    <TextCM style={styles.txt400small}>
                      {t('eContract.GS.history.operateDay')}
                    </TextCM>
                    <TextCM style={styles.txt500small}>
                      {DateUtils.convertDateToDDMMYYYYhhmm(
                        item.lastModifiedDate,
                      )}
                    </TextCM>
                  </ViewCM>
                </TouchableOpacity>
                {showModalDetail && currentShow === item.id && (
                  <ModalDetailHistoyPassword
                    onClose={toggleModalDetail}
                    isVisible={showModalDetail}
                    type={item.method}
                    data={item}
                  />
                )}
              </ViewCM>
            );
          })}
        </ViewCM>
      </ScrollView>
    );
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('eContract.DC.DocumentTemplate.TxtHistory')}
            </TextCM>
            <ViewCM />
          </ViewCM>
          <ViewCM style={styles.viewBody}>
            {loading ? (
              <ViewCM style={styles.loadingCtn}>
                <ActivityIndicator size={'large'} color={'#262D34'} />
              </ViewCM>
            ) : (
              renderHistory()
            )}
            <ButtonCM onPress={onClose} label={t('eContract.CM.BtnClose')} />
          </ViewCM>
        </ViewCM>
      </ViewCM>
    </Modal>
  );
};

export default ModalHistoryPassword;
