import {createNativeStackNavigator} from '@react-navigation/native-stack';
import {NavigationName} from '../../constants';
import {default as InfoAccountScreen} from '../../screens/info-signature-flow';
import AddDigitalSignature from '../../screens/add-digital-signature';
const Stack = createNativeStackNavigator();

const AccountNavigator = () => {
  return (
    <Stack.Navigator screenOptions={{headerShown: false}}>
      <Stack.Screen
        name={NavigationName.InfoSignature}
        component={InfoAccountScreen}
      />
      <Stack.Screen
        name={NavigationName.InfoDigitalSignature}
        component={AddDigitalSignature}
      />
    </Stack.Navigator>
  );
};

export default AccountNavigator;
