import {isEmpty} from 'lodash';
import React, {FC, useEffect, useMemo, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  FlatList,
  Keyboard,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import styles from './styles';
import InputSearch from '../../../InputSearch';
import {IOrganization} from '../../../../../../../model/interface/envelope.interface';
import TextCM from '../../../../../../../components/Text';
import {IconCheckedRadio, IconRadio} from '../../../../../../../assets/images';
import BottomSheetCM from '../../../../../../../components/BottomSheet';
import {useDocumentStore} from '../../../../../../../navigation/SideMenu/store/app-store';
import {useDocumentServices} from '../../../../../../../hook/apiHook/useApi';

type Props = {
  toggleShowFilter: () => void;
  isShowFilter: boolean;
};

const ModalSortOrganization: FC<Props> = ({toggleShowFilter, isShowFilter}) => {
  const {t} = useTranslation();
  const {setCurrentOrganization, showSortOrganization} = useDocumentStore();

  const currentFocused = useDocumentStore(
    state => state.currentFocusOrganization,
  );

  const [dataOrganization, setOrganization] = useState<IOrganization[]>([]);
  const [searchText, setSearchText] = useState('');
  const [itemFirst, setItemFirst] = useState<any>();

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    DocumentServices.getOrganization().then(data => {
      if (!isEmpty(data)) {
        setOrganization(data);
        setCurrentOrganization(data[0]);
        setItemFirst(data[0]);
      }
    });
  }, []);
  const onPressSetCurrent = (item: IOrganization) => {
    showSortOrganization(false);
    setCurrentOrganization(item);
    setSearchText('');
  };
  const CheckIcon = (item: IOrganization) => {
    return currentFocused?.id === item.id;
  };
  const ListItem = ({item, index}: {item: IOrganization; index: number}) => {
    return (
      <TouchableOpacity
        onPress={() => onPressSetCurrent(item)}
        style={[
          styles.ctnItemOriganization,
          item.id !== itemFirst?.id &&
            isEmpty(searchText) &&
            styles.ctnSubItemOrganization,
        ]}
        key={index}>
        {CheckIcon(item) ? (
          <IconCheckedRadio width={24} height={24} />
        ) : (
          <IconRadio width={24} height={24} />
        )}
        <TextCM style={[styles.txtListOrganization, styles.txtOriganization]}>
          {item.acName}
        </TextCM>
      </TouchableOpacity>
    );
  };
  const filteredDataOrganization = useMemo(() => {
    return dataOrganization.filter(item =>
      item.acName.toLowerCase().includes(searchText.toLowerCase()),
    );
  }, [dataOrganization, searchText]);

  const Content = useMemo(
    () => (
      <View style={{flex: 1}}>
        <InputSearch
          showIconDraw={false}
          setSearchText={setSearchText}
          searchText={searchText}
          onPressFilter={toggleShowFilter}
          styleTextInput={styles.ctnInput}
          containerStyle={styles.ctnViewTextInput}
          isFilter={false}
          placeholder={t('eContract.CM.SearchOzganization')}
        />
        <FlatList
          showsHorizontalScrollIndicator={false}
          showsVerticalScrollIndicator={false}
          keyExtractor={item => item.id.toString()}
          data={filteredDataOrganization}
          renderItem={ListItem}
          onScrollBeginDrag={Keyboard.dismiss}
        />
      </View>
    ),
    [filteredDataOrganization, searchText, t, toggleShowFilter, ListItem],
  );
  return (
    <TouchableWithoutFeedback onPress={Keyboard.dismiss} accessible={false}>
      <BottomSheetCM
        title={t('eContract.NT.TxtOrganization')}
        renderContent={Content}
        onClose={toggleShowFilter}
        isVisible={isShowFilter}
        styleBody={styles.ctnFlatlist}
      />
    </TouchableWithoutFeedback>
  );
};

export default ModalSortOrganization;
