export const createDownloadFileExcel = async (
  data: any[],
  fileName: string,
  onSuccess?: (filePath?: string) => void,
  onError?: () => void,
) => {
  var ws = XLSX.utils.json_to_sheet(data);

  var wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Prova');
  const wbout = XLSX.write(wb, {type: 'binary', bookType: 'xlsx'});
  // Determine the correct directory path based on the platform
  const directoryPath =
    Platform.OS === 'android'
      ? RNFS.DownloadDirectoryPath
      : RNFS.DocumentDirectoryPath;

  const checkFileExists = async (fileName: string) => {
    const fileExists = await RNFS.exists(`${directoryPath}/${fileName}.xlsx`);
    if (!fileExists) {
      return `${directoryPath}/${fileName}.xlsx`;
    } else {
      return checkFileExists(incrementStringWithNumber(fileName));
    }
  };
  const file = await checkFileExists(fileName);
  RNFS.writeFile(file, wbout, 'ascii')
    .then(r => {
      onSuccess?.(file);
    })
    .catch(e => {
      onError?.();
    });
};

export const incrementStringWithNumber = (input: string): string => {
  const regex = /(.*)\((\d+)\)$/;
  const match = input.match(regex);

  if (match) {
    const baseString = match[1];
    const number = parseInt(match[2], 10);
    return `${baseString}(${number + 1})`;
  }

  return `${input}(1)`;
};

export const getDataFromExcelFile = async (
  filePath: string,
): Promise<any[]> => {
  try {
    // Read the file
    const fileData = await RNFS.readFile(filePath, 'base64');

    // Convert the file data to a workbook
    const workbook = XLSX.read(fileData, {type: 'base64'});

    // Get the first sheet name
    const sheetName = workbook.SheetNames[0];

    // Get the first sheet data
    const sheet = workbook.Sheets[sheetName];

    // Convert sheet data to JSON
    const jsonData = XLSX.utils.sheet_to_json(sheet);

    return jsonData;
  } catch (error) {
    console.error('Error reading excel file:', error);
    throw error;
  }
};

export const getDataFromExcelFile2 = async (
  filePath: string,
  columnNames: string[],
): Promise<any[]> => {
  try {
    // Read the file
    const fileData = await RNFS.readFile(filePath, 'base64');

    // Convert the file data to a workbook
    const workbook = XLSX.read(fileData, {type: 'base64'});

    // Get the first sheet name
    const sheetName = workbook.SheetNames[0];

    // Get the first sheet data
    const sheet = workbook.Sheets[sheetName];

    if (isEmpty(sheet['!ref'])) {
      return [];
    }
    // Convert sheet data to JSON with raw option to keep original values as strings
    const jsonData = XLSX.utils.sheet_to_json(sheet, {
      header: columnNames,
      defval: '',
    });

    return jsonData;
  } catch (error) {
    console.error('Error reading excel file:', error);
    throw error;
  }
};

export const mapDataWithColumns = (
  dataTemp: Record<string, any>,
  lsNameColumnExcel: string[],
): Record<string, string> => {
  const mappedData: Record<string, string> = {};

  const keys = Object.keys(dataTemp);
  keys.forEach((key, index) => {
    if (index < lsNameColumnExcel.length) {
      mappedData[lsNameColumnExcel[index]] = key;
    }
  });
  return mappedData;
};

