export const convertDataPartiesExcel = (data: any[]): Record<string, any> => {
  const result = convertMapDataPartiesExcel(data);

  const mappedResult = Object.keys(result).reduce((acc, key) => {
    acc[key] = result[key].value;
    return acc;
  }, {} as Record<string, any>);

  return mappedResult;
};

export const checkIsPhoneNumber = (phoneNumber: string) => {
  // Test the phone number against the regex pattern
  return RegexUtils.REGEX_PHONE_NUMBER_9.test(phoneNumber);
};

export const checkIsEmail = (email: string) => {
  return RegexUtils.FORMAT_EMAIL.test(email);
};

export const sortDataError = (errors: string[]) => {
  // Sort the array alphabetically
  errors.sort();

  // Get the first 10 elements or less
  let sortedErrors = errors.slice(0, 10);

  // If there are more than 10 elements, add "..."
  if (errors.length > 10) {
    sortedErrors.push('...');
  }
  return sortedErrors;
};

export const getFileName = (path?: string): string => {
  if (!path) return '';
  const fileNameWithExtension = path.split('/').pop();
  const fileName = fileNameWithExtension?.split('.').slice(0, -1).join('.');
  return fileName || '';
};
