import React from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import GroupRadio from '../../../../../components/GroupRadio';

type ModalListOrgProp = {
  onClose: () => void;
  isVisible: boolean;
  data: any[];
  onPress: (item: any) => void;
  itemSelected: any;
};

const ModalListOrg = ({
  onClose,
  isVisible,
  data,
  onPress,
  itemSelected,
}: ModalListOrgProp) => {
  const {t} = useTranslation();
  const hanndleOnpress = (item: any) => {
    onPress(item);
    onClose();
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{t('eContract.SU.Organization')}</TextCM>
            <View />
          </View>
          <View style={styles.viewBody}>
            <TextCM style={styles.txtLabel}>
              {t('eContract.DC.chooseOrganization')}
            </TextCM>
            <GroupRadio
              data={data}
              onPressData={hanndleOnpress}
              currentValue={itemSelected}
              scrollEnabled={true}
            />
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default ModalListOrg;
