import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity} from 'react-native';
import styles from './styles';
import {getListTypeLogin} from '../ModalCreateConfig/helper';
import GroupRadio, {GroupData} from '../../../../../components/GroupRadio';
import TextCM from '../../../../../components/Text';
import {View as ViewCM} from 'react-native';
import {IconBlackDown} from '../../../../../assets/images';
import BottomSheetCM from '../../../../../components/BottomSheet';
import {useAppSelector} from '../../../../../hook/useRedux';
import {useGeneralSettingFlowStore} from '../../../store/generalSettingFlowStore';
type Props = {
  value?: GroupData;
  onPicType: (value: GroupData | undefined) => void;
};

const PicTypeView = ({value, onPicType}: Props) => {
  const {t} = useTranslation();

  const [isVisible, setIsVisible] = useState<boolean>(false);

  const togglePicType = () => {
    setIsVisible(!isVisible);
  };

  return (
    <>
      <TouchableOpacity style={styles.btnPicType} onPress={togglePicType}>
        {value ? (
          <ViewCM style={styles.viewValue}>
            <TextCM style={styles.txtLabel}>
              {t('eContract.GS.configSecurityLogin.TxtTypeLogin')}
            </TextCM>
            <TextCM style={styles.txtType} numberOfLines={1}>
              {t(value?.label)}
            </TextCM>
          </ViewCM>
        ) : (
          <TextCM style={styles.txtNoType}>
            {t('eContract.GS.configSecurityLogin.TxtTypeLogin')}
          </TextCM>
        )}
        <IconBlackDown width={32} height={32} />
      </TouchableOpacity>
      <BottomSheetCM
        renderContent={
          <ContentPicTypeView
            value={value}
            onPicType={onPicType}
            togglePicType={togglePicType}
          />
        }
        title={t('eContract.GS.configSecurityLogin.TxtTypeLogin')}
        onClose={togglePicType}
        isVisible={isVisible}
      />
    </>
  );
};

type ContentPicTypeViewProps = {
  value?: GroupData;
  onPicType: (value: GroupData | undefined) => void;
  togglePicType: () => void;
};

const ContentPicTypeView = ({
  value,
  onPicType,
  togglePicType,
}: ContentPicTypeViewProps) => {
  const {t} = useTranslation();

  const {listData, currentEdit} = useGeneralSettingFlowStore();

  const [type, setType] = useState<GroupData | undefined>(value);

  const onPressData = (value: GroupData) => {
    togglePicType();
    onPicType(value);
  };

  const getLsData = () => {
    return getListTypeLogin().filter(
      item =>
        !listData.map((item: any) => item.type).includes(item.id) ||
        item.id === currentEdit?.type,
    );
  };

  return (
    <ViewCM style={styles.viewPicType}>
      <TextCM style={styles.txtTitlePicType}>
        {t('eContract.GS.configSecurityLogin.TxtPicTypeLogin')}
      </TextCM>
      <GroupRadio
        data={getLsData() as GroupData[]}
        onPressData={onPressData}
        currentValue={type as GroupData}
        containerStyle={styles.viewGroupRadio}
      />
    </ViewCM>
  );
};

export default PicTypeView;
