import {View, Text} from 'react-native';
import React, {useCallback, useState} from 'react';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import SortDateView from './components/SortDateView';
import {getDataSortDate} from './components/SortDateView/helper';
import {GroupData} from '../../../../../components/GroupRadio';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';

type Props = {
  toggleShowFilter: () => void;
  isShowFilter: boolean;
  onFilter: (data: any) => void;
  filterData: {sort: string};
};

const ModalFilter = ({
  toggleShowFilter,
  isShowFilter,
  filterData,
  onFilter,
}: Props) => {
  const {t} = useTranslation();
  const [sortDate, setSortDate] = useState<GroupData | null>(
    getDataSortDate().find(i => i.id === filterData.sort) as GroupData,
  );

  const onPressFilter = () => {
    toggleShowFilter();
    onFilter({
      sort: sortDate?.id,
    });
  };

  const onPressRemoveFilter = () => {
    toggleShowFilter();
    onFilter({});
  };

  const Content = () => {
    return (
      <View>
        <View style={styles.viewDate}>
          <SortDateView
            data={sortDate as GroupData}
            onChangeSortDate={setSortDate}
          />
        </View>
        <View style={styles.footer}>
          <ButtonCM
            label={t('eContract.DC.modal.BtnRemoveFilter')}
            type="white"
            onPress={onPressRemoveFilter}
            style={styles.btnFooter}
          />
          <ButtonCM
            label={t('eContract.DC.modal.BtnFilter')}
            onPress={onPressFilter}
            style={styles.btnFooter}
          />
        </View>
      </View>
    );
  };

  return (
    <>
      <BottomSheetCM
        title={t('eContract.DC.modal.TxtFilter')}
        renderContent={<Content />}
        onClose={toggleShowFilter}
        isVisible={isShowFilter}
      />
    </>
  );
};

export default ModalFilter;
